// NEET UG Biology: Anatomy of flowering plants (NCERT Class 11, Chapter 6). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `pa-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}

// ---------------------------------------------------------------- Level 1
mc(1, 'meristems', 'A tissue whose cells keep dividing and add new cells to the plant body is called', 'meristematic tissue', ['permanent tissue', 'ground tissue', 'conducting tissue'], 'Meristems have cells that are capable of division. Their daughter cells become permanent tissues.');
mc(1, 'simple tissues', 'The cell wall of parenchyma is', 'thin and made of cellulose', ['thick and lignified', 'thickened at the corners with pectin only', 'suberised and impermeable'], 'Parenchyma cells have thin cellulosic walls and are usually isodiametric. They store food, and when they have chloroplasts they photosynthesise.');
mc(1, 'simple tissues', 'Which of these tissues is made of dead cells at maturity?', 'Sclerenchyma', ['Parenchyma', 'Collenchyma', 'Companion cells'], 'Sclerenchyma cells have thick lignified walls, narrow lumens and usually no protoplasts when mature, so they are dead.');
mc(1, 'complex tissues', 'Water and minerals are conducted upward mainly by', 'xylem', ['phloem', 'cambium', 'cortex'], 'Xylem carries water and minerals from the root to other parts. Phloem carries food.');
mc(1, 'complex tissues', 'Food is transported in a plant through', 'phloem', ['xylem', 'collenchyma', 'sclerenchyma'], 'Phloem conducts food (mainly sucrose) from the leaves to storage and growing regions.');
mc(1, 'complex tissues', 'Which cells are closely associated with sieve tube elements in angiosperms?', 'Companion cells', ['Tracheids', 'Sclereids', 'Guard cells'], 'Each sieve tube element has one or more companion cells, joined to it by pit fields, which keep the enucleate sieve tube working.');
mc(1, 'tissue systems', 'In most dicot leaves, each guard cell is', 'bean-shaped', ['dumb-bell shaped', 'rectangular', 'star-shaped'], 'Guard cells are bean-shaped in dicots. In grasses they are dumb-bell shaped.');
mc(1, 'root anatomy', 'The waxy suberin bands in the radial walls of the endodermis are called', 'Casparian strips', ['pit fields', 'sieve plates', 'bulliform cells'], 'Endodermal cells have deposits of suberin in the form of Casparian strips, which are impermeable to water.');
mc(1, 'secondary growth', 'The dark, central, non-conducting part of an old tree trunk is the', 'heartwood', ['sapwood', 'spring wood', 'phelloderm'], 'Heartwood is dark with tannins, resins and other compounds, and it no longer conducts water. Sapwood is the light, peripheral, conducting part.');
mc(1, 'secondary growth', 'The meristem that produces cork is called', 'phellogen (cork cambium)', ['fascicular cambium', 'interfascicular cambium', 'intercalary meristem'], 'Phellogen cuts off phellem (cork) outwards and phelloderm inwards.');
mc(1, 'secondary growth', 'The age of a tree can be estimated by counting its', 'annual rings', ['lenticels', 'medullary rays', 'root hairs'], 'One annual ring (a pair of spring wood and autumn wood) forms every year in a tree that grows in seasons.');
mc(1, 'secondary growth', 'Lenticels in the bark help in', 'exchange of gases', ['storage of food', 'conduction of water', 'cell division'], 'Lenticels are lens-shaped openings in the cork through which oxygen and carbon dioxide pass.');
mc(1, 'stem anatomy', 'In a monocot stem the vascular bundles are', 'scattered in the ground tissue', ['arranged in a ring', 'present only in the cortex', 'present only at the centre'], 'A monocot stem has many scattered, closed vascular bundles, each with a sclerenchymatous bundle sheath.');
mc(1, 'leaf anatomy', 'In a dorsiventral leaf the palisade parenchyma lies', 'just below the upper epidermis', ['just above the lower epidermis', 'in the middle of the vein', 'inside the guard cells'], 'The palisade cells are elongated, vertical and closely packed on the adaxial (upper) side. The spongy parenchyma is below them.');
mc(1, 'tissue systems', 'The three tissue systems of a plant are', 'epidermal, ground and vascular', ['epidermal, cortical and cambial', 'ground, xylem and phloem', 'meristematic, simple and complex'], 'Plant tissues are grouped by structure and position into epidermal, ground and vascular tissue systems.');

// ---------------------------------------------------------------- Level 2
mc(2, 'meristems', 'Apical meristems are found', 'at the root tip and shoot tip', ['at the base of internodes only', 'in the cortex of old stems', 'between xylem and phloem in monocots'], 'The apical meristem produces the primary tissues and makes the plant longer. Intercalary meristems are at the base of internodes or leaves.');
mc(2, 'meristems', 'A grass keeps growing after being grazed because of its', 'intercalary meristem', ['apical meristem only', 'cork cambium', 'interfascicular cambium'], 'Intercalary meristems are located between mature tissues (leaf base, nodes) and let grasses regenerate after cutting or grazing.');
mc(2, 'meristems', 'Which of these is a lateral meristem?', 'Cork cambium', ['Root apical meristem', 'Intercalary meristem at the node', 'Shoot apical meristem'], 'Lateral meristems (fascicular and interfascicular cambium, cork cambium) lie along the sides and cause secondary growth in girth.');
mc(2, 'simple tissues', 'Collenchyma is commonly found in', 'the hypodermis of dicot stems', ['dicot roots', 'monocot stems', 'the xylem of angiosperms'], 'Collenchyma occurs in layers below the epidermis of dicot stems. It is absent in monocots and roots.', 'Collenchyma is absent in roots and monocots.');
mc(2, 'simple tissues', 'Collenchyma cells have walls thickened at the corners because of deposition of', 'cellulose, hemicellulose and pectin', ['lignin and suberin', 'cutin and wax', 'tannin and resin'], 'The corner thickening gives flexible mechanical support to growing parts. Lignin belongs to sclerenchyma.');
mc(2, 'simple tissues', 'Sclereids are found in', 'the pulp of guava and pear fruits', ['the hypodermis of sunflower', 'the epidermis of leaves', 'the sieve tubes of pumpkin'], 'Sclereids are spherical, oval or cylindrical dead cells with very thick walls and narrow cavities, found in fruit walls, seed coats and tea leaves. They make guava pulp gritty.');
mc(2, 'complex tissues', 'Xylem of gymnosperms lacks', 'vessels', ['tracheids', 'xylem parenchyma', 'xylem fibres'], 'Vessels are characteristic of angiosperms. Gymnosperm xylem has tracheids as the water-conducting elements.');
mc(2, 'complex tissues', 'The only living cells of xylem are', 'xylem parenchyma cells', ['vessel members', 'tracheids', 'xylem fibres'], 'Tracheids, vessels and fibres are dead at maturity. Xylem parenchyma stores food and helps in sideways conduction.');
mc(2, 'complex tissues', 'Phloem of gymnosperms has', 'sieve cells and albuminous cells', ['sieve tubes and companion cells', 'vessels and tracheids', 'sieve tubes only'], 'Gymnosperms lack sieve tubes and companion cells; they have sieve cells with albuminous cells.');
mc(2, 'complex tissues', 'The one dead element in phloem is', 'phloem fibre', ['sieve tube element', 'companion cell', 'phloem parenchyma'], 'Phloem fibres (bast fibres) are sclerenchymatous and dead. Jute fibres are from this tissue.', 'Sieve tube elements lose their nucleus but are still living.');
mc(2, 'complex tissues', 'In which condition is the protoxylem towards the centre and metaxylem towards the periphery?', 'Endarch, as in stems', ['Exarch, as in stems', 'Exarch, as in roots', 'Endarch, as in roots'], 'In stems protoxylem lies towards the pith (endarch). In roots it lies towards the periphery (exarch).', 'Roots are exarch, stems are endarch.');
mc(2, 'tissue systems', 'Root hairs are', 'unicellular elongations of epidermal cells', ['multicellular outgrowths of the epidermis', 'outgrowths of the cortex', 'parts of the root cap'], 'Root hairs absorb water and minerals. Multicellular epidermal hairs on stems are called trichomes.');
mc(2, 'tissue systems', 'In a vascular bundle with cambium between xylem and phloem, the bundle is', 'open', ['closed', 'radial', 'concentric only'], 'Dicot stems have open bundles, with cambium. Monocot bundles are closed.');
mc(2, 'tissue systems', 'Xylem and phloem lying on alternate radii is called', 'radial arrangement', ['conjoint arrangement', 'bicollateral arrangement', 'collateral arrangement'], 'Roots have radial bundles. In conjoint bundles, xylem and phloem lie together on the same radius.');
mc(2, 'tissue systems', 'The ground tissue system in a leaf is mainly the', 'mesophyll', ['epidermis', 'bundle sheath only', 'cambium'], 'The ground tissue is all tissue other than epidermis and vascular bundles. In leaves it is the mesophyll.');
mc(2, 'root anatomy', 'In a typical dicot root, the xylem is usually', 'two to four patches (diarch to tetrarch)', ['more than six patches', 'scattered all over', 'absent'], 'Monocot roots have more than six xylem bundles (polyarch).');
mc(2, 'root anatomy', 'Lateral roots arise from the', 'pericycle', ['endodermis', 'epidermis', 'cortex'], 'Pericycle cells are meristematic enough to start lateral roots and also take part in forming the vascular cambium.');
mc(2, 'stem anatomy', 'Which of these is found in a dicot stem but not in a monocot stem?', 'Collenchymatous hypodermis and a ring of vascular bundles', ['Closed vascular bundles', 'Sclerenchymatous bundle sheath', 'Scattered vascular bundles'], 'Dicot stems have a collenchymatous hypodermis, a ring of open bundles and large pith. The monocot features are the other three.');
mc(2, 'leaf anatomy', 'Bulliform cells are present in the', 'upper epidermis of grass leaves', ['lower epidermis of dicot leaves', 'xylem of grass stems', 'cork of woody stems'], 'Large, empty, colourless bulliform cells help the leaf roll inward when water is short.');
mc(2, 'secondary growth', 'Interfascicular cambium arises from', 'parenchyma cells of the medullary rays', ['pericycle', 'endodermis', 'phloem fibres'], 'Medullary ray cells in line with fascicular cambium turn meristematic, joining it into a continuous ring.');
mc(2, 'secondary growth', 'The wood formed during spring is', 'lighter, with wider vessels', ['darker, with narrow vessels', 'the same as autumn wood', 'always heartwood'], 'Spring (early) wood has wide vessels and lighter colour and lower density. Autumn (late) wood is darker and denser.');
mc(2, 'secondary growth', 'Phelloderm is', 'the living secondary cortex formed inward by cork cambium', ['dead cork formed outward by cork cambium', 'the cork cambium itself', 'a type of heartwood'], 'Phellogen produces phellem outward (dead, suberised) and phelloderm inward (living parenchyma).');
mc(2, 'secondary growth', 'Bark includes', 'all tissues outside the vascular cambium', ['only the cork', 'only the secondary phloem', 'all tissues inside the vascular cambium'], 'Bark is a non-technical term for periderm and everything external to the vascular cambium, including secondary phloem.');

// ---------------------------------------------------------------- Level 3
mc(3, 'complex tissues', 'Which of the following is NOT a component of xylem in angiosperms?', 'Companion cells', ['Vessels', 'Xylem fibres', 'Xylem parenchyma'], 'Xylem has tracheids, vessels, fibres and parenchyma. Companion cells are phloem cells.', 'Option elimination: companion cells belong to phloem.');
mc(3, 'complex tissues', 'A sieve tube element at maturity has', 'no nucleus, but a peripheral cytoplasm and a large vacuole', ['a nucleus but no vacuole', 'no cytoplasm and a lignified wall', 'a nucleus and a lignified wall'], 'The sieve tube element is enucleate and is controlled by the nucleus of the companion cell. Its end walls form perforated sieve plates.', 'It is alive, though it has no nucleus.');
mc(3, 'complex tissues', 'Phloem parenchyma is absent in', 'most monocots', ['all dicots', 'all gymnosperms', 'all pteridophytes only'], 'Phloem parenchyma is present in dicots and absent in most monocots. This is one of the features of the monocot stem.');
mc(3, 'complex tissues', 'Which pair is correctly matched with its main function?', 'Tracheid: water conduction and support', ['Sclerenchyma fibre: food storage', 'Companion cell: water transport', 'Collenchyma: dead mechanical tissue'], 'Tracheids are lignified, dead, and conduct water while supporting. Fibres give mechanical strength; collenchyma is living.');
mc(3, 'complex tissues', 'Vessels are formed of', 'many vessel members joined end to end with perforations', ['single long cells with sieve plates', 'living cells with companion cells', 'living cells with dense cytoplasm'], 'A vessel member has a lignified wall and a large cavity. End walls are perforated so that the members make a tube.');
mc(3, 'tissue systems', 'Which of the following is part of the stomatal apparatus?', 'Stomatal aperture, guard cells and subsidiary cells', ['Guard cells only', 'Epidermal cells and trichomes', 'Mesophyll and palisade cells'], 'The aperture, guard cells and neighbouring subsidiary cells together are the stomatal apparatus.');
mc(3, 'tissue systems', 'Guard cells differ from ordinary epidermal cells in having', 'chloroplasts', ['no nucleus', 'a suberised wall', 'a thick cuticle on both sides'], 'Epidermal cells generally lack chloroplasts except guard cells. Guard cell walls are thin on the outer side and thick next to the aperture.');
mc(3, 'tissue systems', 'The inner wall (towards the pore) of a guard cell is', 'highly thickened', ['thin', 'suberised', 'absent'], 'The thick inner wall and thin outer wall let the guard cells bend and change the pore size when turgor changes.', 'Outer wall thin, inner wall thick.');
mc(3, 'root anatomy', 'In a dicot root, the tissue between xylem and phloem is the', 'conjunctive tissue', ['pericycle', 'endodermis', 'hypodermis'], 'Parenchymatous conjunctive tissue lies between xylem and phloem bundles. Pith is small or inconspicuous.');
mc(3, 'root anatomy', 'Which statement about a monocot root is correct?', 'It has well-developed pith and polyarch xylem', ['It has a small pith and tetrarch xylem', 'It undergoes secondary growth', 'It has no endodermis'], 'Monocot roots have more than six xylem bundles and a large pith. They lack secondary growth.');
mc(3, 'root anatomy', 'Order of layers from outside to inside in a dicot root is', 'epidermis, cortex, endodermis, pericycle, vascular bundles, pith', ['epidermis, endodermis, cortex, pericycle, pith, vascular bundles', 'epidermis, cortex, pericycle, endodermis, vascular bundles, pith', 'cortex, epidermis, endodermis, pericycle, pith, xylem'], 'The endodermis is the innermost layer of the cortex and is outside the pericycle.', 'Pericycle lies inside the endodermis.');
mc(3, 'stem anatomy', 'In a dicot stem, the starch-rich innermost layer of cortex is the', 'endodermis', ['pericycle', 'hypodermis', 'medullary ray'], 'It is also called the starch sheath. The pericycle has semilunar patches of sclerenchyma lying above each bundle.');
mc(3, 'stem anatomy', 'The pericycle of a dicot stem is', 'in the form of semilunar patches of sclerenchyma', ['a single layer of collenchyma', 'a continuous layer of parenchyma', 'absent'], 'The patches occur above the vascular bundles. The medullary rays lie between bundles.');
mc(3, 'stem anatomy', 'A monocot stem differs from a dicot stem in having', 'a sclerenchymatous bundle sheath around each bundle', ['a ring of vascular bundles', 'open vascular bundles', 'a well-differentiated cortex and pith'], 'The ground tissue is not differentiated into cortex, pericycle, medullary rays and pith. Bundles are closed and scattered.');
mc(3, 'stem anatomy', 'A water-containing cavity in the vascular bundle of a monocot stem is found', 'in the protoxylem region', ['in the phloem', 'in the bundle sheath', 'in the epidermis'], 'The cavities form when protoxylem elements disintegrate.');
mc(3, 'leaf anatomy', 'In a dorsiventral leaf, stomata are', 'usually more on the lower epidermis', ['only on the upper epidermis', 'absent', 'only on the midrib'], 'Lower-surface stomata reduce water loss. Isobilateral (monocot) leaves have stomata on both surfaces.');
mc(3, 'leaf anatomy', 'In an isobilateral leaf, the mesophyll is', 'not differentiated into palisade and spongy parenchyma', ['differentiated into palisade and spongy', 'absent', 'made of sclerenchyma'], 'Monocot (isobilateral) leaves have similar upper and lower surfaces.');
mc(3, 'leaf anatomy', 'Vascular bundles in a leaf are surrounded by', 'thick-walled bundle sheath cells', ['guard cells', 'a layer of cork', 'a layer of phellogen'], 'The bundle sheath is a layer of thick-walled cells around the vein.');
mc(3, 'secondary growth', 'In a dicot stem the vascular cambium forms more', 'secondary xylem than secondary phloem', ['secondary phloem than secondary xylem', 'cork than xylem', 'pith than phloem'], 'The cambium is more active on the inner side, so a thick mass of secondary xylem builds up (wood) while the phloem layer remains thin.');
mc(3, 'secondary growth', 'During secondary growth, the primary phloem is', 'crushed by the pressure of secondary tissues', ['pushed to the centre', 'converted into cork', 'unaffected'], 'Primary xylem remains near the pith. Primary phloem gets crushed and becomes non-functional.');
mc(3, 'secondary growth', 'Secondary medullary rays are formed by', 'vascular cambium', ['cork cambium', 'intercalary meristem', 'procambium of root tip'], 'The cambial ring cuts off some radially running parenchyma, forming rays through secondary xylem and phloem.');
mc(3, 'secondary growth', 'Heartwood is resistant to attack by microbes and insects because it contains', 'tannins, resins, oils and gums', ['starch and sugar', 'chlorophyll', 'only lignin'], 'Organic compounds deposited in the cells make it hard, durable, dark and anti-microbial.');
mc(3, 'secondary growth', 'Sapwood is', 'the light-coloured outer xylem that conducts water', ['the dark central dead xylem', 'the cork layer', 'the secondary phloem'], 'The outer, younger secondary xylem is the sapwood. The core is heartwood.');
mc(3, 'secondary growth', 'Cork cells are impervious to water because of', 'suberin deposition in the walls', ['lignin deposition', 'cutin in the cytoplasm', 'cellulose thickening'], 'Phellem cells are dead and have suberised walls.', 'Suberin (cork); cutin (cuticle).');
mc(3, 'secondary growth', 'Periderm consists of', 'phellogen, phellem and phelloderm', ['phellem and cortex', 'cambium, xylem and phloem', 'epidermis and cortex'], 'Periderm is the cork cambium and the tissues it produces on both sides.');
mc(3, 'secondary growth', 'Lenticels form in the cork where', 'the phellogen cuts off loosely arranged parenchyma cells', ['the cork cells are thicker', 'xylem is exposed', 'cambium is absent'], 'This loose complementary tissue breaks the cork layer so gases can pass.');
mc(3, 'secondary growth', 'The ring of vascular cambium in a dicot stem is made of', 'fascicular and interfascicular cambium', ['phellogen and phelloderm', 'procambium and protoxylem', 'only fascicular cambium'], 'Cambium within bundles (intrafascicular) plus cambium formed from medullary ray cells (interfascicular) make a continuous ring.');
mc(3, 'secondary growth', 'Autumn wood has', 'narrower vessels and appears darker', ['wider vessels and appears lighter', 'no xylem', 'only phloem'], 'Cambium is less active in autumn, so the cells are narrow, dense and dark.');
mc(3, 'secondary growth', 'Early and late wood of the same year together make', 'one annual ring', ['two annual rings', 'one heartwood band', 'one growth ring of phloem'], 'Spring wood plus autumn wood form one ring per year in the temperate-zone pattern.', 'Do not count both layers as two years.');

// ---------------------------------------------------------------- Assertion and Reason
asr(2, 'simple tissues', 'Collenchyma gives flexible support to growing stems.', 'Collenchyma cells are living and have thick walls at the corners made of cellulose, hemicellulose and pectin.', 0, 'Both are true. The living, unevenly thickened but non-lignified wall allows the tissue to stretch while supporting, so R explains A.');
asr(3, 'complex tissues', 'Sieve tube elements can conduct food although they have no nucleus.', 'Companion cells are connected to the sieve tube elements by pit fields and control their activities.', 0, 'Both are true. The nucleus of the companion cell runs the sieve tube element, so R explains A.');
asr(3, 'complex tissues', 'Xylem fibres give mechanical strength to the xylem.', 'Xylem fibres have highly thickened, lignified walls with very narrow lumens.', 0, 'Both are true. The thick lignified walls are what make the fibres strong, so R explains A.');
asr(4, 'tissue systems', 'The monocot stem has closed vascular bundles.', 'Closed vascular bundles lack cambium between xylem and phloem.', 0, 'Both are true. A bundle without cambium is called closed, and monocots therefore do not show secondary growth.');
asr(3, 'root anatomy', 'Endodermis is the innermost layer of the cortex in roots.', 'Endodermis has Casparian strips of suberin on its radial and tangential walls and forms the outer boundary of the stele.', 1, 'Both are true. But the Casparian strips do not explain why it is the innermost layer; it is simply the position of the layer.');
asr(4, 'secondary growth', 'Heartwood does not conduct water.', 'Heartwood cells are living and rich in starch.', 2, 'A is true: the dead, tannin- and resin-filled core does not conduct. R is false, because heartwood is made of dead, non-conducting cells.');
asr(4, 'leaf anatomy', 'Grasses can reduce water loss in dry weather by rolling their leaves.', 'Bulliform cells in the lower epidermis of grass leaves are small, thick-walled and lose water first.', 2, 'A is true; R is false. Bulliform cells are large, empty, thin-walled and colourless, and lie in the upper epidermis. When they lose turgor the leaf rolls inward.', 'Bulliform cells are large and in the upper epidermis.');
asr(4, 'meristems', 'Primary growth is caused by apical meristems.', 'The lateral meristems are responsible for the increase in the length of the plant.', 2, 'A is true. R is false because lateral meristems increase the girth (secondary growth); apical (and intercalary) meristems increase length.');
asr(5, 'secondary growth', 'The vascular cambium in a dicot root appears as a wavy ring at first.', 'In roots, the cambium arises partly from tissue below the phloem bundles and partly from the pericycle opposite the protoxylem.', 0, 'Both are true. Cambial strips formed below the phloem join with pericycle-derived strips opposite the protoxylem, making a wavy ring; later it becomes circular. So R explains A.');
asr(5, 'tissue systems', 'Grasses have dumb-bell shaped guard cells.', 'Dicot guard cells are bean-shaped with the thick inner wall.', 1, 'Both are true statements but R does not explain A: it just describes dicots.');

// ---------------------------------------------------------------- Statements
stm(2, 'meristems', 'The intercalary meristem is located between mature tissues.', 'Intercalary meristems are involved in secondary growth of dicot trees.', 2, 'I is true: they lie at the base of leaves or internodes in grasses. II is false because they are primary meristems, so they do not cause secondary growth.');
stm(3, 'simple tissues', 'Parenchyma cells may be photosynthetic.', 'Sclerenchyma cells at maturity have living protoplasts with thin walls.', 2, 'I is true (chlorenchyma). II is false; mature sclerenchyma is dead with thick lignified walls and usually no protoplasts.');
stm(3, 'complex tissues', 'Tracheids and vessels are the main water-conducting elements of angiosperm xylem.', 'Tracheids occur only in gymnosperms.', 2, 'I is true. II is false: tracheids are present in angiosperms too; gymnosperms have tracheids but no vessels.');
stm(4, 'complex tissues', 'In roots, protoxylem lies towards the periphery.', 'In stems, protoxylem lies towards the pith.', 0, 'Exarch roots, endarch stems. Both are correct.');
stm(3, 'stem anatomy', 'A dicot stem has vascular bundles arranged in a ring.', 'A dicot stem has bundles that are conjoint, open and with phloem towards the pith.', 2, 'I is true. II is false: in conjoint collateral bundles the xylem is towards the pith and phloem towards the periphery.');
stm(4, 'root anatomy', 'Monocot roots show secondary growth after some years.', 'A monocot root has polyarch xylem and a large pith.', 3, 'I is false because monocot roots have no cambium and no secondary growth. II is correct.');
stm(4, 'secondary growth', 'Cork cambium forms cork outwards and secondary cortex inwards.', 'Cork cells are living and have thin walls with lots of cytoplasm.', 2, 'I is true. II is false: phellem cells are dead, suberised and impermeable.');
stm(4, 'secondary growth', 'Annual rings are usually well marked in plants growing in places with distinct seasons.', 'Spring wood and autumn wood form two separate rings each year.', 2, 'I is true. II is false: both together form one annual ring.');
stm(5, 'tissue systems', 'Bicollateral bundles have phloem on both sides of the xylem.', 'Radial bundles show xylem and phloem on the same radius, as in dicot stems.', 2, 'I is true (as in cucurbit stems). II is false: radial means different radii (roots); the same radius is conjoint.');
stm(5, 'leaf anatomy', 'Stomata are present on both surfaces of an isobilateral leaf.', 'The mesophyll of an isobilateral leaf is differentiated into palisade and spongy tissue.', 2, 'I is true. II is false; isobilateral leaves have undifferentiated mesophyll.');

// ---------------------------------------------------------------- Match the following
match(2, 'tissues', 'pam1', 'Tissue and feature', ['A. Parenchyma', 'B. Collenchyma', 'C. Sclerenchyma', 'D. Phloem'], ['p. Dead cells with lignified walls and narrow lumens', 'q. Corners thickened with cellulose, hemicellulose and pectin', 'r. Thin-walled cells that store food and photosynthesise', 's. Has companion cells in angiosperms'], 'A-r, B-q, C-p, D-s', ['A-q, B-r, C-p, D-s', 'A-r, B-q, C-s, D-p', 'A-p, B-q, C-r, D-s'], 'Parenchyma has thin walls and does storage and photosynthesis. Collenchyma has the corner thickening, sclerenchyma is dead and lignified, and phloem has companion cells.');
match(3, 'anatomy', 'pam2', 'Organ and feature', ['A. Dicot stem', 'B. Monocot stem', 'C. Dicot root', 'D. Monocot root'], ['p. Polyarch xylem, large pith', 'q. Two to four xylem patches, pith small or absent', 'r. Open bundles in a ring', 's. Closed scattered bundles with sclerenchymatous sheath'], 'A-r, B-s, C-q, D-p', ['A-s, B-r, C-q, D-p', 'A-r, B-s, C-p, D-q', 'A-q, B-s, C-r, D-p'], 'Dicot stem: bundles in a ring, open. Monocot stem: scattered, closed. Dicot root: 2 to 4 xylem bundles. Monocot root: more than six.');
match(4, 'secondary growth', 'pam3', 'Structure and nature', ['A. Phellogen', 'B. Phellem', 'C. Phelloderm', 'D. Lenticel'], ['p. Dead, suberised cells', 'q. Living secondary cortex', 'r. Lateral meristem producing periderm', 's. Gas exchange pore in the bark'], 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-q, C-p, D-s', 'A-r, B-p, C-s, D-q'], 'Phellogen is the meristem; phellem is dead cork; phelloderm is living cortex; the lenticel allows gas exchange.');
match(3, 'wood', 'pam4', 'Wood type and property', ['A. Heartwood', 'B. Sapwood', 'C. Spring wood', 'D. Autumn wood'], ['p. Light colour, wide vessels', 'q. Peripheral, conducts water', 'r. Dense and dark, narrow cells', 's. Central, with tannins, non-conducting'], 'A-s, B-q, C-p, D-r', ['A-q, B-s, C-p, D-r', 'A-s, B-q, C-r, D-p', 'A-p, B-q, C-s, D-r'], 'Heartwood is central and dark with deposits. Sapwood is outer and conducts. Spring wood is lighter with wide vessels and autumn wood is denser and darker.', 'Spring is light, autumn is dark.');

// ---------------------------------------------------------------- Passages
pass('pap1', 'Passage: a stem section', 'A student cuts a thin transverse section of a young stem. She sees many vascular bundles scattered through the section. Each bundle is surrounded by thick-walled cells. There is no cambium in the bundle, and the ground tissue is a single mass of parenchyma that shows no clear cortex or pith. The peripheral bundles are smaller than those at the centre. A water-containing cavity is present in each bundle near the protoxylem.');
pq('pap1', 3, 'stem anatomy', 'The section is of a', 'monocot stem', ['dicot stem', 'dicot root', 'gymnosperm stem'], 'Scattered closed bundles with sclerenchymatous sheath and undifferentiated ground tissue indicate a monocot stem.');
pq('pap1', 3, 'stem anatomy', 'This stem will not form a thick woody trunk by secondary growth because', 'its bundles are closed and have no cambium', ['it has no phloem', 'it has no xylem', 'it has a cork cambium'], 'No cambium means no lateral meristem for cutting off new xylem and phloem, so no secondary growth in girth.');
pq('pap1', 4, 'stem anatomy', 'The tissue that is usually absent from the phloem of this stem is', 'phloem parenchyma', ['sieve tubes', 'companion cells', 'xylem'], 'In monocots, phloem parenchyma is absent. Sieve tubes and companion cells are present.', 'Remember: monocots lack phloem parenchyma.');
pass('pap2', 'Passage: a log of wood', 'A cross-section of an old dicot tree trunk shows a dark central region, a lighter ring around it, alternating light and dark concentric rings, and an outer dark layer with small raised pores. Rays run from the centre outward.');
pq('pap2', 3, 'secondary growth', 'The dark central region is most likely', 'heartwood', ['sapwood', 'primary phloem', 'phelloderm'], 'The dark non-conducting core is heartwood, loaded with tannins, resins and oils.');
pq('pap2', 4, 'secondary growth', 'The small raised pores in the outer layer are', 'lenticels, for exchange of gases', ['stomata of the epidermis', 'resin ducts for conducting water', 'root hair bases'], 'The epidermis is replaced by periderm in older stems. Lenticels in the bark allow gas exchange.', 'Not stomata: the epidermis is shed.');
pq('pap2', 4, 'secondary growth', 'The rays running outward are', 'secondary medullary rays made of parenchyma', ['xylem vessels', 'sieve tubes', 'cork cells'], 'Radially elongated parenchyma cells formed by the cambium carry food and water sideways.');

// ---------------------------------------------------------------- Level 4 and 5 (mixed concepts)
mc(4, 'complex tissues', 'Which combination of features is correct for angiosperm phloem?', 'Sieve tube elements, companion cells, phloem parenchyma and phloem fibres', ['Sieve cells, albuminous cells, phloem parenchyma and fibres', 'Sieve tubes, tracheids and companion cells', 'Vessels, companion cells and fibres'], 'Angiosperm phloem has four elements. Sieve cells and albuminous cells are gymnosperm features.');
mc(4, 'complex tissues', 'Among xylem elements, which pair contains only dead cells?', 'Tracheids and vessels', ['Vessels and xylem parenchyma', 'Xylem parenchyma and fibres', 'Tracheids and xylem parenchyma'], 'Xylem parenchyma is the only living component; all others are dead.', 'Do not choose parenchyma as dead.');
mc(4, 'simple tissues', 'Which of these is NOT correctly paired?', 'Sclerenchyma: found abundantly in the hypodermis of dicot stems', ['Collenchyma: hypodermis of dicot stems', 'Parenchyma: pulp of fruit', 'Sclereids: seed coat of legumes'], 'The hypodermis of a dicot stem is collenchymatous. Sclerenchyma occurs in monocot hypodermis.', 'Reversed in monocots and dicots.');
mc(4, 'tissue systems', 'Which of these is correct about trichomes?', 'They are usually multicellular and may be branched or secretory', ['They are unicellular and absorb water', 'They are guard cell derivatives', 'They are made of cork'], 'Trichomes are epidermal hairs. They prevent water loss and some secrete substances. Root hairs are unicellular and are different.');
mc(4, 'tissue systems', 'The epidermis of a stem generally lacks chloroplasts except', 'in guard cells', ['in trichomes', 'in cork', 'in root cap'], 'This is a standard feature of epidermal cells. Guard cells have chloroplasts.');
mc(4, 'root anatomy', 'Which statement about the pericycle in a dicot root is NOT correct?', 'It is a single layer of dead cells', ['It lies just inside the endodermis', 'It gives rise to lateral roots', 'It helps to form vascular cambium'], 'The pericycle is made of living, thick-walled parenchyma cells, in one or few layers.');
mc(4, 'root anatomy', 'In a dicot root, the first cambium strips to appear are', 'below the phloem bundles', ['opposite the protoxylem', 'in the cortex', 'in the epidermis'], 'Conjunctive tissue below the phloem forms cambial strips first, later joined by pericycle cells opposite the protoxylem.');
mc(4, 'stem anatomy', 'A stem section shows a ring of conjoint, open, endarch bundles and a large pith. It is a', 'dicot stem', ['monocot stem', 'dicot root', 'monocot root'], 'A ring arrangement and open cambium-bearing bundles are the dicot stem features; roots are radial and exarch.');
mc(4, 'leaf anatomy', 'In a dorsiventral leaf, which statement is correct?', 'The spongy parenchyma has large intercellular spaces for gas exchange', ['The palisade cells are loosely arranged', 'The lower epidermis lacks stomata', 'Bulliform cells are present'], 'Spongy parenchyma cells are loosely arranged and are near the lower epidermis. Palisade cells are tightly packed.');
mc(4, 'leaf anatomy', 'Which is a feature of both isobilateral and dorsiventral leaves?', 'Vascular bundles surrounded by a bundle sheath', ['Palisade and spongy parenchyma', 'Bulliform cells', 'Parallel venation'], 'Both leaf types have bundles with a sheath. The other features belong only to one type.');
mc(4, 'secondary growth', 'In secondary growth of a dicot stem, which tissue is formed first?', 'Interfascicular cambium, joining the fascicular cambium to make a ring', ['Cork cambium, followed by vascular cambium', 'Heartwood', 'Annual ring'], 'The cambial ring must first form; only then are secondary xylem and phloem cut off.');
mc(4, 'secondary growth', 'Which of the following is true of bark?', 'It includes periderm and the secondary phloem outside the cambium', ['It includes only the cork', 'It contains secondary xylem', 'It is formed only in monocots'], 'Bark: early (soft) bark in the first year and late (hard) bark later.');
mc(4, 'secondary growth', 'The activity of the cork cambium is different from that of the vascular cambium because it', 'produces dead cork outward and living secondary cortex inward', ['produces xylem and phloem', 'is present in monocots only', 'is formed from the pericycle in all stems'], 'In stems it usually develops in the cortex. Its products replace the epidermis.');
mc(4, 'secondary growth', 'A tree that grows in a place with no seasonal change will show', 'poorly marked or no annual rings', ['very clear annual rings', 'no heartwood', 'no cambium'], 'Annual rings depend on seasonal change in cambial activity.');
mc(4, 'secondary growth', 'Which of the following is the correct sequence from the outside inwards in a woody dicot stem?', 'Periderm, secondary phloem, vascular cambium, secondary xylem', ['Secondary phloem, periderm, cambium, xylem', 'Periderm, cambium, secondary phloem, xylem', 'Cambium, periderm, xylem, phloem'], 'Cambium cuts off phloem outward and xylem inward, so phloem is just outside the cambium.');
mc(4, 'meristems', 'The tissue derived from the procambium of an apical meristem is', 'primary xylem and primary phloem', ['epidermis', 'cortex', 'cork'], 'Protoderm forms epidermis, ground meristem forms ground tissue, procambium forms primary vascular tissue.');
mc(4, 'mixed', 'The movement of water across a root from the soil to the xylem is forced into the symplast at the', 'endodermis, because of the Casparian strips', ['epidermis, because of the cuticle', 'pericycle, because of the cambium', 'cortex, because of the starch sheath'], 'The suberised strips block the apoplast pathway, so water must pass through the cell membrane of the endodermal cells. This is the link between root anatomy and plant water relations.');
mc(5, 'secondary growth', 'Which of the following is the correct place for the origin of the vascular cambium in a dicot root?', 'Conjunctive tissue below the phloem and pericycle above the protoxylem', ['Cortex and epidermis', 'Endodermis only', 'Pith and medullary rays'], 'Roots lack pre-formed cambium. It originates from conjunctive tissue and the pericycle. After this the dicot root grows as a dicot stem.');
mc(5, 'complex tissues', 'Which of these tissues is made of only one type of cell and is always dead at maturity?', 'Sclerenchyma', ['Xylem', 'Phloem', 'Collenchyma'], 'Sclerenchyma is a simple tissue (fibres or sclereids), all dead. Xylem has living parenchyma, phloem has living sieve tubes, and collenchyma is living.', 'Xylem is mostly dead but not wholly.');
mc(5, 'tissue systems', 'Choose the option that is correct for both a dicot root and a monocot root.', 'Vascular bundles are radial and xylem is exarch', ['Xylem is endarch', 'Pith is large and well developed', 'They show secondary growth'], 'Roots are radial and exarch in both. Pith: large in monocots, small in dicots. Secondary growth only in dicots.');
mc(5, 'mixed', 'How many of these are living at maturity: sieve tube element, vessel, collenchyma, companion cell, phloem fibre, xylem parenchyma, phellem?', 'Four', ['Three', 'Five', 'Two'], 'Living: sieve tube element, collenchyma, companion cell, xylem parenchyma = 4. Dead: vessel, phloem fibre, phellem.', 'Sieve tube element is living.');
mc(5, 'secondary growth', 'Which statement about periderm is correct?', 'It replaces the epidermis in old stems and roots', ['It is formed by the vascular cambium', 'It is a primary tissue', 'It contains secondary xylem'], 'Cork cambium makes the periderm. The epidermis is stretched and shed.');

// ---------------------------------------------------------------- Expansion (added 2026-11-22)
// ---- Level 2
mc(2, 'meristem', 'The cells of meristematic tissue are', 'thin walled, dense in cytoplasm and capable of dividing', ['thick walled and dead', 'large with a big central vacuole and no division', 'lignified and tube-like'], 'Meristematic cells are living, with dense cytoplasm, prominent nuclei and few or no vacuoles. They keep dividing.');
mc(2, 'meristem', 'Which meristem is responsible for increase in the girth of a tree trunk?', 'Lateral meristem', ['Apical meristem', 'Intercalary meristem', 'Root cap'], 'Vascular cambium and cork cambium (lateral meristems) add secondary tissues and increase thickness.');
mc(2, 'simple', 'Parenchyma cells are usually', 'isodiametric with thin cellulosic walls', ['elongated with lignified walls', 'dead and hollow', 'thickened only at the corners with pectin'], 'Parenchyma is the least specialised permanent tissue. It does photosynthesis, storage and secretion.');
mc(2, 'simple', 'Sclerenchyma cells are', 'dead at maturity with thick lignified walls', ['living with thin walls', 'living with corner thickenings', 'sieve-like'], 'Their walls are so thick that the lumen is small. Fibres and sclereids are of this type.');
mc(2, 'simple', 'The gritty texture of the pulp of pear is due to', 'sclereids', ['collenchyma', 'sieve tubes', 'vessels'], 'Sclereids are spherical, oval or cylindrical dead cells with a narrow cavity. They are found in the pulp of guava, pear and sapota.');
mc(2, 'complex', 'Xylem and phloem are called complex tissues because', 'each is made of more than one kind of cell working together', ['they are made of one kind of cell', 'they have no walls', 'they are made only of dead cells'], 'A complex tissue has different cell types working as a unit.');
mc(2, 'complex', 'Which cells of phloem are living and have a nucleus and help the sieve tube elements?', 'Companion cells', ['Phloem fibres', 'Tracheids', 'Vessels'], 'Companion cells are connected by pit fields with the sieve tube and keep it alive.');
mc(2, 'epidermal', 'The waxy layer on the aerial parts of a plant that reduces water loss is the', 'cuticle', ['pericycle', 'endodermis', 'hypodermis'], 'The cuticle is a layer of cutin on the epidermis.');
mc(2, 'epidermal', 'Trichomes on the stem epidermis are usually', 'multicellular hair-like outgrowths', ['unicellular tubes', 'part of the xylem', 'dead cork cells'], 'Trichomes may be branched or unbranched, soft or stiff, and may be secretory. They reduce water loss by transpiration.', 'Root hairs, not trichomes, are unicellular.');
mc(2, 'root', 'The innermost layer of the cortex in a root is the', 'endodermis', ['epidermis', 'pericycle', 'pith'], 'The endodermis has a single layer of barrel-shaped cells.');
mc(2, 'leaf', 'The photosynthetic tissue of a leaf is the', 'mesophyll', ['cuticle', 'xylem', 'cork'], 'Mesophyll lies between the upper and lower epidermis.');
mc(2, 'secondary', 'The age of a tree in a temperate climate can be estimated by counting', 'annual rings', ['lenticels', 'root hairs', 'stomata'], 'Each year the cambium makes a ring of early wood and late wood.');

// ---- Level 3
mc(3, 'meristem', 'Which of the following give rise to the primary body of the plant?', 'Apical meristems', ['Lateral meristems', 'Cork cambium', 'Vascular cambium'], 'Apical meristems at root and shoot tips produce primary tissues and increase length.');
mc(3, 'meristem', 'The tissues produced from the apical meristem first appear as', 'protoderm, procambium and ground meristem', ['phellem, phelloderm and cambium', 'xylem, phloem and cork', 'epidermis, periderm and bark'], 'Protoderm gives epidermis; procambium gives primary xylem and phloem; ground meristem gives ground tissue.');
mc(3, 'simple', 'Which statement about collenchyma is correct?', 'It is absent in monocots and in roots, and gives mechanical support to growing parts', ['It has lignified walls', 'It is dead at maturity', 'It is made of dead fibres'], 'Collenchyma is living, with cellulose, hemicellulose and pectin deposition at corners.');
mc(3, 'simple', 'In which pair is the function correctly assigned?', 'Parenchyma: storage; sclerenchyma: mechanical support', ['Parenchyma: mechanical strength; collenchyma: storage', 'Collenchyma: conduction; sclerenchyma: photosynthesis', 'Sclerenchyma: photosynthesis; parenchyma: conduction of water'], 'Parenchyma stores and photosynthesises. Sclerenchyma supports.');
mc(3, 'simple', 'Which of the following is found in the seed coats of legumes and in the leaves of tea?', 'Sclereids', ['Companion cells', 'Vessels', 'Collenchyma'], 'Sclereids are found in fruit walls of nuts, pulp of fruits, seed coats of legumes and leaves of tea.');
mc(3, 'simple', 'Sclerenchyma fibres are usually', 'long, narrow cells with pointed ends and thick walls', ['spherical with a wide lumen', 'tube-like with sieve plates', 'living cells with chloroplasts'], 'Fibres are used commercially for making ropes and textiles.');
mc(3, 'complex', 'The conducting cells of xylem that are most characteristic of angiosperms are', 'vessels', ['tracheids', 'sieve cells', 'companion cells'], 'Vessels are long, tube-like with perforated end walls. Tracheids are present in all vascular plants, while vessels are mainly in angiosperms.');
mc(3, 'complex', 'The cytoplasm of a mature sieve tube element is present', 'as a thin peripheral layer', ['throughout filling the cell', 'only around the nucleus', 'not at all'], 'It lacks a nucleus and has a peripheral cytoplasm with a large vacuole in the middle.');
mc(3, 'complex', 'Xylem parenchyma stores', 'starch or fat and may store tannins', ['only water', 'only hormones', 'only proteins'], 'It is the living tissue of xylem and also helps in lateral conduction of water.');
mc(3, 'complex', 'Companion cells are absent in', 'gymnosperms', ['angiosperms', 'monocots', 'dicots'], 'In gymnosperms, sieve cells have albuminous cells instead of companion cells.');
mc(3, 'epidermal', 'The subsidiary cells of a stomatal apparatus are', 'epidermal cells next to the guard cells', ['guard cells themselves', 'cells of the endodermis', 'cells of the xylem'], 'Some epidermal cells near the guard cells become specialised as subsidiary cells.');
mc(3, 'epidermal', 'Root hairs are formed from', 'epidermal cells', ['endodermis', 'pericycle', 'cortex'], 'Root hairs are unicellular elongations of epidermal cells and absorb water and minerals.');
mc(3, 'root', 'The Casparian strips of the endodermis are made of', 'suberin', ['cellulose', 'lignin only', 'chitin'], 'The tangential and radial walls of endodermal cells have deposits of the water-impermeable waxy suberin.');
mc(3, 'root', 'The pericycle of a dicot root gives rise to', 'lateral roots and part of vascular cambium', ['root cap', 'root hairs', 'epidermis'], 'Pericycle cells have meristematic activity.');
mc(3, 'root', 'The number of xylem bundles in a dicot root is', 'usually two to four (di- to tetrarch)', ['more than six', 'always one', 'scattered with no pattern'], 'Dicot roots have two to four xylem and phloem patches. Monocot roots have more than six (polyarch).');
mc(3, 'root', 'The pith is', 'small or inconspicuous in a dicot root', ['large and well developed in a dicot root', 'absent in monocot roots', 'full of tracheids'], 'Monocot roots have a large, well developed pith.');
mc(3, 'stem', 'The hypodermis of a dicot stem is', 'collenchymatous', ['sclerenchymatous', 'parenchymatous with chloroplasts', 'suberised'], 'In monocot stems the hypodermis is sclerenchymatous.');
mc(3, 'stem', 'In a monocot stem the ground tissue is', 'undifferentiated into cortex and pith, with scattered bundles', ['differentiated into cortex, endodermis and pith', 'made of xylem only', 'made of cork'], 'The vascular bundles are scattered in a parenchymatous ground tissue.');
mc(3, 'stem', 'The vascular bundles of a monocot stem are', 'conjoint and closed, with a sclerenchymatous sheath', ['radial and open', 'conjoint and open', 'bicollateral'], 'Cambium is absent, so they are closed.');
mc(3, 'stem', 'The central part of a dicot stem is occupied by', 'a large pith of parenchyma', ['a sclerenchymatous core', 'cork', 'protoxylem'], 'The pith is large and well developed in dicot stems.');
mc(3, 'leaf', 'The cells of the palisade parenchyma are', 'elongated and arranged vertically, below the upper epidermis', ['spherical with large air spaces', 'dead and thick walled', 'arranged near the lower epidermis'], 'Spongy parenchyma is loosely arranged with air spaces near the lower epidermis.');
mc(3, 'leaf', 'Stomata in grass leaves differ from those in dicots in that their guard cells are', 'dumb-bell shaped', ['kidney shaped', 'thick walled all round', 'absent'], 'NCERT: the guard cells of grasses are dumb-bell shaped.');
mc(3, 'leaf', 'The leaf of a monocot such as a grass shows', 'isobilateral structure with undifferentiated mesophyll', ['palisade only on the upper side', 'no stomata', 'bulliform cells in the lower epidermis only'], 'Both surfaces have stomata and the mesophyll is not differentiated.');
mc(3, 'secondary', 'The cork cambium is also called', 'phellogen', ['phellem', 'phelloderm', 'procambium'], 'Phellogen cuts off phellem (cork) outside and phelloderm inside.');
mc(3, 'secondary', 'Which tissue of the periderm is formed on the inner side of the cork cambium?', 'Secondary cortex (phelloderm)', ['Cork (phellem)', 'Sapwood', 'Heartwood'], 'Phelloderm is parenchymatous.');
mc(3, 'secondary', 'Lenticels permit', 'exchange of gases between the stem and the air', ['absorption of water', 'conduction of sugars', 'formation of annual rings'], 'They are lens-shaped openings in the cork, with loosely arranged complementary cells.');
mc(3, 'secondary', 'The dark coloured central wood of an old tree trunk is', 'heartwood', ['sapwood', 'spring wood', 'cork'], 'It is filled with tannins, resins, oils, gums and aromatic substances.');
mc(3, 'secondary', 'Which is correct for secondary xylem and secondary phloem in a dicot stem?', 'More secondary xylem is formed than secondary phloem', ['More phloem than xylem', 'Equal amounts always', 'Only phloem forms'], 'The cambium is more active on the inner side, so secondary xylem forms a compact mass.');

asr(2, 'simple', 'Sclerenchyma gives strength to the plant body.', 'Its cell walls are heavily lignified.', 0, 'Lignin makes the thick wall rigid, so R explains A.');
asr(3, 'epidermal', 'Root hairs absorb water and minerals efficiently.', 'Root hairs are unicellular outgrowths of the epidermis that greatly increase the surface area.', 0, 'The large surface area aids absorption.');
asr(3, 'complex', 'Vessels are more efficient in water conduction than tracheids.', 'Vessels are tubes formed of cells with perforated end walls.', 0, 'Perforations allow water to flow end to end without crossing walls.');
asr(3, 'simple', 'Collenchyma cells are dead at maturity.', 'Sclerenchyma cells are dead at maturity.', 3, 'A is false: collenchyma is a living tissue. R is true.');
asr(4, 'root', 'Endodermis controls the movement of water into the xylem of the root.', 'Casparian strips of suberin block movement of water along the walls of endodermal cells.', 0, 'Water must pass through the cell membranes of endodermal cells.');
asr(4, 'secondary', 'Bark protects the tree from loss of water and from infection.', 'The cork cells of bark have suberin deposits and are dead.', 0, 'Suberised dead cork cells are impervious to water and gases, so R explains A.');
asr(4, 'stem', 'Monocot stems do not show secondary growth.', 'Monocot vascular bundles are open.', 2, 'A is true. R is false: monocot bundles are closed with no cambium.');
asr(5, 'secondary', 'Heartwood is darker than sapwood.', 'Heartwood has tannins, resins and oils deposited in it.', 0, 'The deposits give dark colour and durability.');
asr(5, 'complex', 'Vessels are the main conducting elements in gymnosperm xylem.', 'Tracheids are the water-conducting cells of gymnosperm xylem.', 3, 'A is false: gymnosperm xylem lacks vessels. R is true.');
asr(5, 'root', 'The pericycle of a dicot root can give rise to lateral roots.', 'Pericycle cells keep meristematic activity.', 0, 'Because pericycle cells can still divide, they can form lateral root primordia, so R explains A.');

stm(3, 'complex', 'Vessels are dead cells of the xylem.', 'Xylem parenchyma is living.', 0, 'Both are correct.');
stm(3, 'simple', 'Collenchyma has cellulose, hemicellulose and pectin at its corners.', 'Collenchyma has lignified walls.', 2, 'II is false: lignin is typical of sclerenchyma and xylem walls.');
stm(3, 'meristem', 'Intercalary meristem is present between mature tissues in grasses.', 'It is a lateral meristem.', 2, 'I is true; II is false, it is a part of the primary meristem.');
stm(4, 'root', 'In a dicot root the endodermis has Casparian strips.', 'In a monocot root the pith is large.', 0, 'Both are correct.');
stm(4, 'stem', 'A dicot stem has a collenchymatous hypodermis.', 'A monocot stem has a sclerenchymatous hypodermis.', 0, 'Both are correct.');
stm(4, 'secondary', 'Sapwood conducts water.', 'Heartwood conducts water better than sapwood.', 2, 'Heartwood does not conduct water.');
stm(4, 'epidermal', 'Stomata regulate transpiration and gas exchange.', 'Guard cells of dicots are bean shaped.', 0, 'Both are correct: kidney or bean shaped.');
mc(4, 'complex', 'Consider: (i) Vessels are living. (ii) Sieve tube elements lack a nucleus. (iii) Tracheids are dead. (iv) Companion cells are present in angiosperm phloem. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(ii), (iii), (iv) are correct. (i) is wrong, vessels are dead.', 'Vessels are dead.', 'statements');
mc(4, 'simple', 'Consider: (i) Parenchyma stores food. (ii) Collenchyma is dead. (iii) Sclereids are dead. (iv) Collenchyma is found below the epidermis of dicot stems. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (iii), (iv) are right. (ii) is wrong, collenchyma is living.', null, 'statements');
mc(5, 'tissue systems', 'Consider: (i) Epidermis is the outermost layer. (ii) Cuticle covers it. (iii) Xylem and phloem are ground tissue. (iv) Pith is ground tissue. (v) Stomata are in the epidermis. How many are correct?', 'Four', ['Three', 'Five', 'Two'], '(i), (ii), (iv), (v) are correct. Xylem and phloem form the vascular system, not the ground tissue.', 'Vascular tissue is separate from ground tissue.', 'statements');
mc(5, 'secondary', 'Consider: (i) Cork is formed by phellogen. (ii) Phelloderm is dead. (iii) Lenticels aid gas exchange. (iv) Heartwood is dark. (v) Sapwood is non-living. How many are correct?', 'Three', ['Two', 'Four', 'Five'], '(i), (iii), (iv) are right. Phelloderm is living parenchyma and sapwood contains living cells with conducting dead vessels.', 'Phelloderm is not dead.', 'statements');
stm(5, 'complex', 'Companion cells are closely associated with sieve tube elements.', 'Phloem fibres are the only living cells of phloem.', 2, 'II is false: sieve tubes, companion cells and phloem parenchyma are living. Phloem fibres are dead.');

// ---- Matches
match(2, 'simple', 'pax1', 'Tissue and feature', ['A. Parenchyma', 'B. Collenchyma', 'C. Sclerenchyma', 'D. Xylem fibre'], ['p. Corner thickening with pectin', 'q. Thin walled and isodiametric', 'r. Lignified and dead', 's. Lignified wall in xylem'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Parenchyma: thin and isodiametric. Collenchyma: corner thickening. Sclerenchyma: lignified, dead. Xylem fibre: lignified fibre of xylem.');
match(3, 'complex', 'pax2', 'Cell and tissue', ['A. Tracheid', 'B. Sieve tube element', 'C. Companion cell', 'D. Phloem fibre'], ['p. Xylem', 'q. Phloem with a nucleus', 'r. Phloem without a nucleus', 's. Phloem, dead'], 'A-p, B-r, C-q, D-s', ['A-p, B-q, C-r, D-s', 'A-r, B-p, C-q, D-s', 'A-p, B-r, C-s, D-q'], 'Tracheid in xylem. Sieve tube lacks nucleus. Companion cells have nuclei. Phloem fibres are dead.');
