match(4, 'secondary', 'pax4', 'Secondary growth term and meaning', ['A. Phellem', 'B. Phelloderm', 'C. Phellogen', 'D. Lenticel'], ['p. Cork cambium', 'q. Secondary cortex', 'r. Cork', 's. Gas exchange pore'], 'A-r, B-q, C-p, D-s', ['A-q, B-r, C-p, D-s', 'A-r, B-q, C-s, D-p', 'A-p, B-q, C-r, D-s'], 'Phellem is cork, phelloderm is secondary cortex, phellogen is cork cambium, lenticel allows gas exchange.');
match(4, 'root', 'pax5', 'Part and feature in a root', ['A. Endodermis', 'B. Pericycle', 'C. Epidermis', 'D. Conjunctive tissue'], ['p. Gives lateral roots', 'q. Casparian strips', 'r. Root hairs', 's. Between xylem and phloem'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-q, B-r, C-p, D-s'], 'Each term has one NCERT function.');
match(4, 'stem', 'pax6', 'Plant and stem feature', ['A. Dicot stem', 'B. Monocot stem', 'C. Dicot root', 'D. Monocot root'], ['p. Scattered closed bundles', 'q. Ring of open bundles', 'r. Two to four xylem arms', 's. More than six xylem arms'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Dicot stem: ring of open bundles. Monocot stem: scattered closed bundles. Dicot root: di- to tetrarch. Monocot root: polyarch.');
match(4, 'leaf', 'pax7', 'Leaf part and feature', ['A. Palisade parenchyma', 'B. Spongy parenchyma', 'C. Bulliform cell', 'D. Bundle sheath'], ['p. Loosely arranged with air spaces', 'q. Elongated cells under the upper epidermis', 'r. Large empty colourless cell that helps rolling', 's. Surrounds vascular bundle'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-q, B-r, C-p, D-s'], 'Leaf anatomy terms.');
match(5, 'secondary', 'pax8', 'Wood and feature', ['A. Early wood', 'B. Late wood', 'C. Heartwood', 'D. Sapwood'], ['p. Lighter colour, wider vessels', 'q. Darker, narrower vessels', 'r. Dark central region without conduction', 's. Outer, lighter, conducts water'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'Spring wood is lighter, autumn wood darker; heartwood central, sapwood peripheral.');
match(5, 'complex', 'pax9', 'Group and its phloem or xylem element', ['A. Gymnosperm phloem', 'B. Angiosperm phloem', 'C. Gymnosperm xylem', 'D. Angiosperm xylem'], ['p. Sieve cells and albuminous cells', 'q. Sieve tubes and companion cells', 'r. Tracheids without vessels', 's. Tracheids and vessels'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-s, C-r, D-q'], 'Gymnosperm phloem has sieve cells and albuminous cells; gymnosperm xylem lacks vessels.');
