pq('pax12', 4, 'stem', 'The starch sheath in S is the', 'innermost layer of the cortex (endodermis)', ['hypodermis', 'pericycle', 'pith'], 'In dicot stems the endodermis is rich in starch grains.');
pass('pax13', 'Passage: a tree trunk', 'A cross-section of a trunk from a temperate forest shows concentric rings of light and dark wood. The central region is dark and has resins and tannins. The outer bark has small raised pores.');
pq('pax13', 3, 'secondary', 'Each pair of light and dark rings stands for', 'one year of growth', ['one month of growth', 'one season of cork', 'a lenticel'], 'Each ring is early wood plus late wood of one year.');
